@pytest.fixture
def postgres_client(monkeypatch):
    url = os.environ["MAP_TEST_DATABASE_URL"]
    schema = "map_test_" + uuid4().hex
    admin = create_engine(url)
    with admin.begin() as db:
        db.execute(text(f"CREATE SCHEMA {schema}"))
    engine = create_engine(
        url, connect_args={"options": f"-csearch_path={schema},public"}
    )
    try:
        with engine.connect() as db:
            db.exec_driver_sql(Path("deploy/migrations/004_map.sql").read_text())
        graph = parse_osm(SOURCE)
        normalize_links(graph)
        geometry, status = geometries(graph)
        with engine.begin() as db:
            persist(db, graph, geometry, status)
            db.execute(text("UPDATE map_dataset SET revision=1"))

        def database():
            with Session(engine) as db:
                yield db

        app.dependency_overrides[get_db] = database
        monkeypatch.setenv("AUTH_REQUIRED", "0")
        with TestClient(app, headers={"origin": "http://localhost:8081"}) as client:
            yield client, engine
    finally:
        app.dependency_overrides.pop(get_db, None)
        engine.dispose()
        with admin.begin() as db:
            db.execute(text(f"DROP SCHEMA {schema} CASCADE"))
        admin.dispose()


def test_query_aliases_tags_bounds_and_detail(postgres_client):
    client, _ = postgres_client
    result = client.get("/api/map/features?q=Library").json()
    assert result["features"][0]["id"] == stable_id("way", 4)
    bike = client.get(
        "/api/map/features?tag_key=amenity&tag_value=bicycle_parking"
    ).json()
    assert len(bike["features"]) == 1
    assert bike["features"][0]["properties"]["capacity"] == "12"
    parking = client.get("/api/map/features?tag_key=amenity&tag_value=parking").json()
    assert len(parking["features"]) == 1
    assert client.get("/api/map/features?bbox=0,0,1,1").json()["features"] == []
    assert client.get("/api/map/features?bbox=bad").status_code == 422
    detail = client.get("/api/map/features/" + stable_id("node", 1)).json()
    assert detail["building_id"] == stable_id("way", 4)
    page = client.get("/api/map/features?limit=1").json()
    second = client.get(
        "/api/map/features", params={"after": page["next"], "limit": 1}
    ).json()
    assert page["features"][0]["id"] != second["features"][0]["id"]


def test_save_audit_conflict_and_stable_building_link(postgres_client):
    client, engine = postgres_client
    snapshot = client.get("/api/map/editor").json()
    building = next(o for o in snapshot["objects"] if o["id"] == stable_id("way", 4))
    building["tags"]["name"] = "New Library Name"
    edit = {"revision": snapshot["revision"], "upserts": [building], "deletes": []}
    response = client.post("/api/map/editor", json=edit)
    assert response.status_code == 200, response.text
    assert response.json()["revision"] == 2
    assert client.post("/api/map/editor", json=edit).status_code == 409
    assert (
        client.get("/api/map/features/" + stable_id("node", 1)).json()["building_id"]
        == building["id"]
    )
    with engine.connect() as db:
        audit = (
            db.execute(
                text(
                    "SELECT actor_email,before_state,after_state FROM map_changes WHERE revision=2"
                )
            )
            .mappings()
            .one()
        )
        assert audit["actor_email"] == "developer@example.test"
        assert audit["before_state"][building["id"]]["tags"]["name"] == "Park Library"
        assert (
            audit["after_state"][building["id"]]["tags"]["name"] == "New Library Name"
        )


def test_referenced_deletion_rolls_back(postgres_client):
    client, _ = postgres_client
    response = client.post(
        "/api/map/editor",
        json={"revision": 1, "upserts": [], "deletes": [stable_id("node", 1)]},
    )
    assert response.status_code == 422
    assert client.get("/api/map/editor").json()["revision"] == 1
    assert client.get("/api/map/features/" + stable_id("node", 1)).status_code == 200


def test_geometry_edits_update_dependent_way(postgres_client):
    client, _ = postgres_client
    snapshot = client.get("/api/map/editor").json()
    node = next(o for o in snapshot["objects"] if o["id"] == stable_id("node", 2))
    node["position"] = [43, -84.002]
    response = client.post(
        "/api/map/editor", json={"revision": 1, "upserts": [node], "deletes": []}
    )
    assert response.status_code == 200, response.text
    building = client.get("/api/map/features/" + stable_id("way", 4)).json()
    assert building["version"] == 2
    assert [-84.002, 43.0] in building["geometry"]["coordinates"][0]


def test_create_and_delete_point(postgres_client):
    client, _ = postgres_client
    key = "node/" + str(uuid4())
    value = {
        "id": key,
        "type": "node",
        "position": [43, -84],
        "tags": {"amenity": "bicycle_parking", "capacity": "20"},
        "refs": [],
        "building_id": None,
    }
    assert (
        client.post(
            "/api/map/editor", json={"revision": 1, "upserts": [value], "deletes": []}
        ).status_code
        == 200
    )
    assert client.get("/api/map/features/" + key).json()["tags"]["capacity"] == "20"
    assert (
        client.post(
            "/api/map/editor", json={"revision": 2, "upserts": [], "deletes": [key]}
        ).status_code
        == 200
    )
    assert client.get("/api/map/features/" + key).status_code == 404


def test_navigation_search_exact_alias_and_six_results(postgres_client):
    client, engine = postgres_client
    with engine.begin() as db:
        for index, name in enumerate(
            [
                "East Administrative Building",
                "East",
                "East Hall",
                "East A",
                "East B",
                "East C",
                "East D",
                "East E",
            ]
        ):
            key = f"node/{uuid4()}"
            db.execute(
                text(
                    "INSERT INTO map_features(id,object_type,tags,source_tags,geom) VALUES (:id,'node',CAST(:tags AS jsonb),'{}',ST_SetSRID(ST_Point(-84,43),4326))"
                ),
                {"id": key, "tags": json.dumps({"name": name})},
            )
            db.execute(
                text(
                    "INSERT INTO map_names(feature_id,kind,name) VALUES (:id,'name',:name)"
                ),
                {"id": key, "name": name},
            )
            if index == 1:
                db.execute(
                    text(
                        "INSERT INTO map_names(feature_id,kind,name) VALUES (:id,'alt_name','East Alias')"
                    ),
                    {"id": key},
                )
    response = client.get("/api/map/search", params={"q": "East"})
    assert response.status_code == 200, response.text
    results = response.json()["results"]
    assert len(results) == 6
    assert results[0]["name"] == "East"
    assert len({item["id"] for item in results}) == 6
    assert (
        client.get("/api/map/search", params={"q": "East Alias"}).json()["results"][0][
            "name"
        ]
        == "East"
    )


def test_navigation_route_api(postgres_client):
    client, _ = postgres_client
    response = client.get(
        "/api/map/route",
        params={"start": stable_id("node", 2), "destination": stable_id("way", 4)},
    )
    assert response.status_code == 200, response.text
    assert response.json()["properties"]["destination_node"] == stable_id("node", 1)
    assert response.json()["properties"]["revision"] == 1
    assert (
        client.get(
            "/api/map/route",
            params={"start": "missing", "destination": stable_id("way", 4)},
        ).status_code
        == 404
    )
    assert (
        client.get(
            "/api/map/route",
            params={"start": stable_id("node", 5), "destination": stable_id("way", 4)},
        ).status_code
        == 422
    )
